        if x not in conflicts34:
            conflicts34[x] = set()
        conflicts34[x].add(y)
        ptr += 1

    INF = float('inf')

    # Step 1: For each item in cat2, find minimum cost compatible item from cat1
    # dp2[j] = min cost of (1+2) dinner where 2nd course is item j
    dp2 = [INF] * n2
    for j in range(n2):
        # Try to find minimum cost item from cat1 that doesn't conflict
        conflicts = conflicts12.get(j + 1, set())
        # Candidates from cat1 sorted by cost
        idx = sorted(range(n1), key=lambda i: a[i])
        for i in idx:
