    # Step 2: For each item in cat3, find minimum cost compatible (1+2) from cat2
    dp3 = [INF] * n3
    for j in range(n3):
        conflicts = conflicts23.get(j + 1, set())
        idx = sorted(range(n2), key=lambda i: dp2[i])
        for i in idx:
            if i + 1 not in conflicts:
                if dp2[i] < INF:
                    dp3[j] = dp2[i] + c[j]
                    break
        if dp3[j] == INF:
            dp3[j] = INF

    if all(x == INF for x in dp3):
        return "-1\n"

    # Step 3: For each item in cat4, find minimum cost compatible (1+2+3) from cat3
    dp4 = [INF] * n4
    for j in range(n4):
