        edges.append((x, y, w, i + 1))

    return n, m, s, t, edges

def build_graph_from_edges(edges):
    graph = defaultdict(list)
    for i, (x, y, w, idx) in enumerate(edges):
        graph[x].append((y, idx))
        graph[y].append((x, idx))
    return graph

def is_connected_bfs(graph, s, t, blocked_edges):
    visited = set()
    queue = deque([s])
    visited.add(s)

    while queue:
        u = queue.popleft()
        for v, idx in graph[u]:
            if idx not in blocked_edges and v not in visited:
                visited.add(v)
                if v == t:
                    return True
                queue.append(v)

    return t in visited

def min_cut_two_edges(input_str):
    n, m, s, t, edges = parse_input(input_str)

    graph = build_graph_from_edges(edges)

    edge_idx_to_edge = {i[3]: (i[0], i[1], i[2]) for i in edges}

    # Test removing 0 edges
    cached_result = "-1"

    # Check single-edge cuts
    best_single_cost = float('inf')
    best_single_edges = []

    for i in range(m):
        blocked = {edges[i][3]}
        if not is_connected_bfs(graph, s, t, blocked):
            cost = edges[i][2]
            if cost < best_single_cost:
                best_single_cost = cost
                best_single_edges = [edges[i][3]]

    # Check two-edge cuts
    best_two_cost = float('inf')
    best_two_edges = []

    for i in range(m):
        for j in range(i + 1, m):
            blocked = {edges[i][3], edges[j][3]}
            if not is_connected_bfs(graph, s, t, blocked):
                cost = edges[i][2] + edges[j][2]
                if cost < best_two_cost:
                    best_two_cost = cost
                    best_two_edges = [edges[i][3], edges[j][3]]
            elif cost >= best_two_cost:
                continue

    if best_single_cost != float('inf') and best_single_cost <= best_two_cost:
