```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        clauses.append(parts[1:])

    # 2-SAT: each variable i has nodes 2*i (false) and 2*i+1 (true)
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]

    def lit_to_node(x):
        # literal x (positive or negative) to node
        # var x's node: 2*(x-1) is false, 2*(x-1)+1 is true
        idx = abs(x) - 1
        if x > 0:
            return 2 * idx + 1  # x is true
        else:
            return 2 * idx      # ~x is true (not first literal)

    def node_to_lit_var(u):
        return (u // 2) + 1

    for clause in clauses:
        # Clause: l1 OR l2 OR ... OR lk
        # Add implications: for each pair (i,j): ¬li → lj
        for i in range(len(clause)):
            for j in range(len(clause)):
                if i != j:
                    not_lit = -clause[i]
                    lit = clause[j]
                    p = lit_to_node(not_lit)
                    c = lit_to_node(lit)
                    adj[p].append(c)

    # Tarjan's algorithm for SCCs
    ids = [0] * num_nodes
    low = [0] * num_nodes
    on_stack = [False] * num_nodes
    stack = []
    ids_counter = [0]
    scc_ids = [-1] * num_nodes
    scc_count = [0]

    def dfs(u):
        ids[u], low[u] = ids_counter[0], ids_counter[0]
        ids_counter[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if ids[v] == 0:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_ids[v] = scc_count[0]
                if v == u:
                    break
            scc_count[0] += 1

    for i in range(num_nodes):
        if ids[i] == 0:
            dfs(i)

    # Check for unsatisfiability
    for i in range(m):
        # If x_i and ¬x_i are in same SCC, then unsatisfiable
        if scc_ids[2 * i] == scc_ids[2 * i + 1]:
            return "NO\n"

    # Find assignment: if x_true node appears before x_false in topological order
    result = []
    for i in range(m):
        if scc_ids[2 * i + 1] > scc_ids[2 * i]:
            # true node has higher SCC id, so false is chosen
            result.append('0')
        else:
            result.append('1')

    return "YES\n" + "".join(result)
```

This solution implements the standard 2-SAT algorithm:
1. Build an implication graph where each literal `l` has edge `¬l → l'` for every other literal `l'` in the same clause
2. Use Tarjan's algorithm to find strongly connected components
3. If a variable and its negation are in the same SCC, the formula is unsatisfiable
4. Otherwise, assign variables based on SCC topological ordering

The time complexity is O(n + m) for sparse graphs, suitable for the given constraints (n, m ≤ 2·10⁵).

