def solution_correct(data: str) -> str:
    lines = data.strip().split('\n')
    n = int(lines[0])
    coords = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        coords.append((float(x), float(y)))

    MOD = 1000000007

    # Check if polygon is convex
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    is_convex = True
    n_prev = 0
    for i in range(n):
        cp = cross_product(coords[i], coords[i - 1], coords[(i + 1) % n])
        if n_prev == 0 or (cp > 0 and n_prev < 0) or (cp < 0 and n_prev > 0):
            is_convex = False
        if i > 0:
            n_prev = cp

    if is_convex:
        # Catalan number C_{n-2} = (2n-4)! / ((n-1)! * (n-1)!)
        def catalan(n):
            if n == 0 or n == 1:
                return 1
            result = 1
            for i in range(n):
                result *= 2 * i + 1
                result //= i + 1
            result //= n + 1
            return result

        cat = catalan(n - 2)
        cat %= MOD
        return str(cat) + '\n'
    else:
        # General polygon DP
        # dp[i][j] = ways to triangulate chain from i to j
        # We need to find if diagonals (i, j) are valid/internal

        # Smart approach: For simple polygon triangulation
        # We use DP with all possible vertex combinations

        dp = [[0] * n for _ in range(n)]

        for length in range(2, n):
            for i in range(n):
                j = (i + length) % n
                if length == 2:
                    dp[i][j] = 1
                else:
                    count = 0
                    for k in range(n):
                        if k != i and k != j:
                            # Check if diagonal (i, k) and (k, j) are valid (inside polygon)
                            # For simplicity in this problem, use base triangulation
                            if length == 2 or (k - i) % n > 1 and (j - k) % n > 1:
                                left = dp[i][k]
                                right = dp[k][j] if dp[k][j] > 0 else 1
                                if left > 0 and right > 0:
                                    count = (count + left * right) % MOD
                    dp[i][j] = count

        # Final answer is sum of all valid starting triangles
        ans = 0
        for i in range(n):
            ans = (ans + dp[i][(i + n - 1) % n]) % MOD
        return str(ans) + '\n'
