        [(0, 1), (1, 0), (1, 1), (1, 2)],  # T facing right
        [(0, 1), (1, 0), (1, 1), (2, 0)],  # T facing left
        [(0, 1), (1, 1), (1, 0), (2, 1)],  # T facing down
