```python
def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    matrix = []
    for i in range(1, n + 1):
        row = list(map(int, lines[i].split()))
        matrix.append(row)

    # Check if an array is bitonic
    def is_bitonic(arr):
        """Check if arr is bitonic (first increases then decreases)"""
        k = len(arr)
        if k <= 1:
            return True
        if k == 2:
            return arr[0] != arr[1]  # Strict inequality required

        # Find the peak position (where it starts decreasing)
        peak = 0
        for i in range(1, k - 1):
            if arr[i] <= arr[i + 1]:
                continue  # Still increasing
            else:
                peak = i
                break
        else:
            # Entirely non-decreasing
            return arr[-1] > arr[0]

        # Check: increases up to peak
        for i in range(peak):
            if arr[i] >= arr[i + 1]:
                return False

        # Check: decreases after peak
        for i in range(peak + 1, k):
            if arr[i - 1] <= arr[i]:
                return False

        return True

    # Store original matrix as string
    result = []
    for row in matrix:
        result.append(' '.join(map(str, row)))

    # Check all rows are bitonic
    row_bitonic = True
    for row in matrix:
        if not is_bitonic(row):
            row_bitonic = False
            break

    # Check all columns are bitonic
    col_bitonic = True
    for j in range(m):
        col = [matrix[i][j] for i in range(n)]
        if not is_bitonic(col):
            col_bitonic = False
            break

    if row_bitonic and col_bitonic:
        return '\n'.join(result)
    else:
