            new_dp = [0] * (n + 2)
            for j in range(-i, i + 2, 2):
                if j < 0 or j > i:
                    continue
                # dp[i][j] = dp[i-1][j-1] + dp[i-1][j+1] + dp[i-1][j]
                # j-1 from add A, j+1 from add B, j from add C
                top = (j - 1 + i - 1) // 2
                bottom = i - 1 - (j - 1) // 2
                top2 = (j + 1 + i - 1) // 2
                bottom2 = i - 1 - (j + 1) // 2
                top3 = j // 2
                bottom3 = i - 1 - j // 2

                # Use combinations
                def nCk(n, k):
                    if k < 0 or k > n:
                        return 0
                    num = 1
                    den = 1
                    for i in range(k):
                        num = num * (n - i)
                        den = den * (i + 1)
                    return num // den

                a = dp[j-1] if j-1 >= 0 else 0
                b = dp[j+1] if j+1 <= n+1 else 0
                c = dp[j]
                new_dp[j] = (a + b + c) % p
            dp = new_dp

        ans = sum(dp[j] for j in range(l, min(r, n) + 1)) % p
        return str(ans)
    else:
        # For large n, use combinatorics with reflection principle
        def nCk(n, k, mod):
            if k < 0 or k > n:
                return 0
            if k == 0 or k == n:
                return 1
            num = 1
            den = 1
            for i in range(k):
                num = num * (n - i) % mod
                den = den * (i + 1) % mod
            # Modular inverse using Fermat's little theorem (if mod is prime)
            # But p may not be prime, so use extended euclidean
            def modinv(a, m):
                # a*x + m*y = gcd(a, m) = 1
                g, x, _ = extended_gcd(a, m)
                if g != 1:
                    return None
                return x % m
            def extended_gcd(a, b):
                if b == 0:
                    return a, 1, 0
                g, x, y = extended_gcd(b, a % b)
                return g, y, x - (a // b) * y
            den_inv = modinv(den, mod)
            return (num * den_inv) % mod

        ans = 0
        for j in range(l, min(r, n) + 1):
            # For each final balance j, sum over valid num of C customers
            for c in range(0, n + 1):
