                # Valid A-B arrangements: C(a+b, a) - C(a+b, a+1)
                term = (nCk(a + b, a, p) - nCk(a + b, a + 1, p)) % p
                term = (term * nCk(n, c, p)) % p
                ans = (ans + term) % p

