def gcd_square_free(n):
    """Compute the square-free part of n by dividing out all perfect square factors."""
    result = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            cnt = 0
            while n % d == 0:
                n //= d
                cnt += 1
            if cnt % 2 == 1:
                result *= d
        d += 1
    if n > 1:
        result *= n
    return result

def nCr(n, k):
    """Calculate binomial coefficient C(n,k) modulo MOD."""
    if k < 0 or k > n:
        return 0
    num, den = 1, 1
    for i in range(k):
        num = num * (n - i) % MOD
        den = den * (i + 1) % MOD
    return num * pow(den, MOD - 2, MOD) % MOD

