    freq = {}
    for x in a:
        g = gcd_square_free(x)
        freq[g] = freq.get(g, 0) + 1

    groups = list(freq.values())

    # If only one group, all pairs from same group form perfect squares
    if len(groups) == 1:
        return '0'

    # dp[i] = number of valid ways to place i elements using processed groups
    dp = [0] * (n + 1)
    dp[0] = 1

